_M_SQUARE = tl.constexpr(2)
_M_RECIP = tl.constexpr(3)
_M_RSQRT = tl.constexpr(4)

# Generic-path flags.
_F_INT = 1  # exponent is an integer value
_F_ODD = 2  # exponent is an odd integer (sign of a negative base survives)
_F_ZERO = 4  # exponent is exactly 0 -> 1 everywhere (also 0**0 == 1)
_F_ONE = 8  # exponent is exactly 1 -> identity

_BLOCK = 8192  # 32-bit elements (32 KiB in, 64 KiB fp32 scratch)
_BLOCK_16BIT = 16384  # 16-bit elements: same bytes per tile, fewer tiles
