@triton.jit
def _pow_apply(x, p, MODE: tl.constexpr, FLAGS: tl.constexpr):
    """``x ** p`` for an fp32 vector ``x`` and a uniform fp32 scalar ``p``."""
    if MODE == _M_SQRT:
        return tl.sqrt(x)
    if MODE == _M_SQUARE:
        return x * x
    if MODE == _M_RECIP:
        return 1.0 / x
    if MODE == _M_RSQRT:
        return 1.0 / tl.sqrt(x)
    if FLAGS & 8:  # p == 1
        return x
    if FLAGS & 4:  # p == 0
        return tl.full(x.shape, 1.0, tl.float32)
    y = tl.exp2(p * tl.log2(tl.abs(x)))
    if FLAGS & 2:  # odd integer exponent keeps the sign of a negative base
        y = tl.where(x < 0.0, -y, y)
    if (FLAGS & 1) == 0:  # negative base with a non-integral exponent -> NaN
        y = tl.where(x < 0.0, float("nan"), y)
    return y


@triton.jit
def _pow_tile(
    ptr, n, blk, p, MODE: tl.constexpr, FLAGS: tl.constexpr, BLOCK: tl.constexpr
):
    offs = blk * BLOCK + tl.arange(0, BLOCK)
    mask = offs < n
    x = tl.load(ptr + offs, mask=mask, other=0.0).to(tl.float32)
    y = _pow_apply(x, p, MODE, FLAGS)
    tl.store(ptr + offs, y.to(ptr.dtype.element_ty), mask=mask)


